// Flat production music catalog — 673 canonical tracks, lane-organization removed.
// Source of truth: supabase/functions/_shared/musicCatalog.ts
//
// Step 2 accepted stats migrated from docs/music-catalog-stats-correction-draft.ts.
// Step 3-1 accepted genre classification migrated from
//   docs/music-catalog-genre-classification-revised-draft.ts.
//
// Canonical order: first-occurrence order from the former 21-lane catalog,
// skipping alternate-video-ID entries and cross-lane duplicates.
// Matches the Step 2 / Step 3 accepted 673-track canonical ordering.
//
// To reduce YouTube API usage, manually add youtubeVideoId to any catalog track.
// Tracks without youtubeVideoId fall back to YouTube search.

import type { PrimaryGenre, Subgenre } from "./musicGenreTaxonomy.ts";

export type TrackEnergy = "low" | "medium" | "high";

// Step 2 accepted 30-dimension profile.
// 10 atmosphere dims + 7 desired-sound dims, each on a 0-100 scale.
export type TrackStats = {
  brightness: number;
  warmth: number;
  openness: number;
  motion: number;
  intimacy: number;
  socialEnergy: number;
  tension: number;
  nostalgia: number;
  playfulness: number;
  dreaminess: number;

  energy: number;
  groove: number;
  density: number;
  acousticness: number;
  electronicness: number;
  vocalPresence: number;
  climaxIntensity: number;
};

// 4 season dims + 5 time-of-day dims + 4 weather dims, each on a 0-100 scale.
export type TrackAffinity = {
  spring: number;
  summer: number;
  autumn: number;
  winter: number;

  morning: number;
  day: number;
  dusk: number;
  night: number;
  lateNight: number;

  clear: number;
  cloudy: number;
  rain: number;
  snow: number;
};

export type CatalogTrack = {
  title: string;
  artist: string;
  // Verified YouTube videoId — when present analyze-and-search skips YouTube search API.
  youtubeVideoId?: string;
  energy: TrackEnergy;
  moodTags: string[];
  sceneTags: string[];
  subTags?: string[];
  // Step 2 accepted stat/affinity enrichment. All 673 tracks carry valid values.
  stats?: TrackStats;
  affinity?: TrackAffinity;
  alternateVideoIds?: string[];
  statConfidence?: number;
  needsStatReview?: boolean;
  statReviewNotes?: string[];
  // Step 3-1 accepted genre classification. Required for all 673 tracks.
  primaryGenre: PrimaryGenre;
  subgenre: Subgenre;
  crossoverGenres: Subgenre[];
  genreConfidence: number;
  needsGenreReview: boolean;
  genreReason: string;
};

// Backward-compatible alias — remove after all call sites migrate to CatalogTrack.
export type CatalogSeedTrack = CatalogTrack;

