// Backward-compatible alias — points to the same flat catalog.
// Remove after consumers are updated to import MUSIC_CATALOG directly.
export const ALL_SEED_TRACKS: readonly CatalogTrack[] = MUSIC_CATALOG;

// youtubeVideoId가 non-empty string인 track만 "verified"로 본다.
export function hasYoutubeVideoId(track: CatalogTrack): boolean {
  return typeof track.youtubeVideoId === "string" && track.youtubeVideoId.trim().length > 0;
}

function hashString(input: string): number {
  let hash = 2166136261;

  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash +=
      (hash << 1) +
      (hash << 4) +
      (hash << 7) +
      (hash << 8) +
      (hash << 24);
  }

  return hash >>> 0;
}

function seededRandom(seed: number): () => number {
  let value = seed;

  return () => {
    value = (value * 1664525 + 1013904223) >>> 0;
    return value / 4294967296;
  };
}

function seededShuffle<T>(items: T[], seedText: string): T[] {
  const shuffled = [...items];
  const random = seededRandom(hashString(seedText));

  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  return shuffled;
}

// Flat catalog candidate selection — seeded shuffle over all 673 tracks.
// laneId no longer narrows the pool; every track is a candidate.
export function selectFlatCatalogTracks(params: {
  seed: string;
  count?: number;
}): CatalogTrack[] {
  const { seed, count = 10 } = params;
  return seededShuffle([...MUSIC_CATALOG], seed).slice(0, count);
}

// Like selectFlatCatalogTracks but restricted to tracks with a verified youtubeVideoId.
export function selectVerifiedFlatCatalogTracks(params: {
  seed: string;
  count?: number;
}): CatalogTrack[] {
  const { seed, count = 10 } = params;
  const verified = MUSIC_CATALOG.filter(hasYoutubeVideoId);
  if (verified.length === 0) return [];
  return seededShuffle([...verified], `${seed}:verified`).slice(0, count);
}

const VALID_ENERGIES: TrackEnergy[] = ["low", "medium", "high"];

// Fatal catalog structure errors throw; less critical issues are warnings.
export function validateCatalog(): void {
  const seen = new Set<string>();
  const altSeen = new Set<string>();

  for (const track of MUSIC_CATALOG) {
    if (!track.title || !track.title.trim() || !track.artist || !track.artist.trim()) {
      throw new Error(
        `Invalid catalog track: missing title or artist for "${track.title ?? "unknown"}" by "${track.artist ?? "unknown"}"`,
      );
    }
    if (!track.energy || !VALID_ENERGIES.includes(track.energy)) {
      throw new Error(
        `Invalid catalog track energy "${track.energy}" for "${track.title}" by "${track.artist}"`,
      );
    }
    if (!track.youtubeVideoId || track.youtubeVideoId.trim().length === 0) {
      throw new Error(`Missing or blank youtubeVideoId for "${track.title}" by "${track.artist}"`);
    }
    if (seen.has(track.youtubeVideoId)) {
      throw new Error(
        `Duplicate youtubeVideoId "${track.youtubeVideoId}" for "${track.title}" by "${track.artist}"`,
      );
    }
    seen.add(track.youtubeVideoId);

    for (const alt of (track.alternateVideoIds || [])) {
      if (seen.has(alt) || altSeen.has(alt)) {
        throw new Error(
          `alternateVideoId "${alt}" on track "${track.title}" collides with an existing primary or alternate ID`,
        );
      }
      altSeen.add(alt);
    }
  }
}
